examples.code:
const bands = $xover($saw('c2'), {
  lowMidFreq: '200hz',
  midHighFreq: '2000hz',
})
$mix([
  $comp(bands.low, { threshold: 2.5, ratio: 4 }),
  $comp(bands.mid, { threshold: 3, ratio: 3 }),
  $comp(bands.high, { threshold: 2, ratio: 6 }),
]).out()

const notes = $cycle($p('c3 g3 eb3 bb2'))
$sine(notes)
  .$.fold($perc(notes.trig, { decay: 0.4 }), {
    freq: notes,
  })
  .out()

const grains = $pulse('8hz')
$granular($saw('a3'), grains, {
  time: $sah($noise('white').range(0, 2), grains),
  freq: $cycle($p('[c4, e4, g4] [b3, d4, g4]')),
  rootFreq: 'a3',
  width: 4,
  spread: 2,
  mix: 4,
}).out()

const grains = $pulse('8hz')
$granularSampler($wavs().pad, grains, {
  time: $sah($noise('white').range(0, 5), grains),
  width: 4,
  spread: 2,
}).out()

const grains = $pulse('8hz')
const cloud = $granular($saw('a3'), grains, {
  mix: 4,
  quality: 'dirtyTape',
})
$reverb($wowFlutter(cloud), 3, { size: 5, tone: 2 }).out()

const pluck = $saw($cycle($p('c3 eb3 g3 bb3'))).amp(
  $perc($clock.beatTrigger, { decay: 0.3 }),
)
$clockedDelay(pluck, {
  bars: 1 / 16,
  shape: 1,
  feedback: 2,
  mix: 3,
}).out()

const seq = $cycle($p('c4 g4 eb4 <bb4 f4>'))
$macro(seq, 'modalResonator', {
  trigger: seq.trig,
  timbre: 1,
  lpgDecay: 3,
}).out()

const seq = $cycle($p('c3 eb3 g3 bb3'))
const env = $perc(seq.trig, { decay: 0.5 })
$wavetable(seq, $wavs().tables.pad, env.range(0, 4))
  .amp(env)
  .out()

const seq = $cycle($p('c2 [c2 c3] eb2 [g1 bb1]'))
$jup6f(
  $saw(seq),
  $perc(seq.trig, { decay: 0.15 }).range('c3', 'c6'),
  4,
).bp.out()

$saw('c2')
  .$.eq({
    sections: [
      { type: 'lowShelf', freq: '150hz', gain: 3 },
      {
        type: 'peak',
        freq: $sine('0.5hz').range('400hz', '2000hz'),
        gain: -6,
        q: 2,
      },
      { type: 'highpass', freq: '40hz' },
    ],
    adaptiveQ: true,
  })
  .out()

$saw(['c2', 'g2'])
  .$.eq({
    sections: [
      [{ type: 'highShelf', freq: '3000hz', gain: -6 }],
      [{ type: 'highShelf', freq: '3000hz', gain: 4 }],
    ],
  })
  .out()

const seq = $cycle($p('c2 [c2 c3] eb2 [g1 bb1]'))
const env = $perc(seq.trig, { decay: 0.2 })
$unstable.filter
  .lp($saw(seq), env.range('c3', 'c6'), 4, {
    drive: 'driven',
  })
  .out()

const pad = $saw($chord('C2[m7]'))
const sweep = $sine('0.1hz').range('c3', 'c6')
$unstable.filter
  .vintageLadder(pad, sweep, 3.5, { compensated: true })
  .out()

const lead = $saw($cycle($p('c3 eb3 g3 bb3')))
const sweep = $sine('0.5hz').range('c4', 'c7')
$unstable.filter
  .k35Lp(lead, sweep, 4, { saturation: 'heavy' })
  .out()

const saw = $saw('c2')
const sweep = $sine('0.2hz').range('c3', 'c6')
const wet = $unstable.filter.cutoffWarpAp(saw, sweep, 3, {
  drive: 'softClip',
  stages: 4,
})
$mix([saw, wet]).out()

const seq = $cycle($p('d2*2 [f2 d3] a1 [c2 ~ d2]'))
$unstable.filter
  .tripole($saw(seq), $sine('0.3hz').range('c3', 'c6'), 3, {
    mode: 'lhl',
  })
  .out()

const burst = $noise('white').amp(
  $perc($clock.beatTrigger, { decay: 0.02 }),
)
const notes = $cycle($p('c3 eb3 g3 bb3'))
$unstable.filter
  .comb(burst, notes, 4.5, { mix: 'full' })
  .out()

const voice = $saw($cycle($p('c3 eb3 g3 ~'))).amp(
  $perc($clock.beatTrigger, { decay: 0.15 }),
)
voice.out()
$delayRead($buffer(voice, 1), 0.375).amp(2.5).out()

const voice = $saw($cycle($p('c3 eb3 g3 ~'))).amp(
  $perc($clock.beatTrigger, { decay: 0.15 }),
)
voice.out()
const echoes = $buffer(voice, 1)
$delayRead(echoes, 0.375).amp(2.5).out()
$delayRead(echoes, 0.75).amp(1.25).out()

const midi = $midiCV({ channels: 4 })
$sine(
  $quantizer($sine('0.1hz').range('c3', 'c5'), midi, {
    gate: midi.gate,
  }),
).out()

$sine(
  $wrap($cycle($p('c2 g5 e3 b4 d6')), 'c4', 'c5', {
    octave: true,
  }),
).out()

argument_spans.description:
Per-source editor argument spans. Consumed entirely TS-side (merged
into the params' `__argument_spans` before IPC) and never read here;
optional on the wire so a hand-built payload may omit it.

examples.code:
const g = $groove({
  timing: [0, 0.3],
  velocity: [1, 0.6],
  grid: 8,
})
const seq = $cycle($p('c4 e4 g4 c5 g4 e4 c4 g3'), {
  groove: g,
  velocity: g.velocity,
})
$sine(seq).amp($adsr(seq.gate)).amp(seq.velocity).out()

const seq = $cycle($p('<[c3, g3] [eb3, bb3]>'))
$grains(seq, $wavs().strings, seq.gate, {
  length: 2,
  density: 3,
  shape: 'tukey',
}).out()

const order = $cycle($p('0 2 1 3 0 0 3 2'))
$sampler($wavs().pad, order.trig, {
  slice: [[0, 0.25, 0.5, 0.75], order],
  fade: 2,
}).out()

const seq = $cycle($p('c3 eb3 g3 bb2'))
const env = $perc(seq.trig, { decay: 0.4 })
$sine(seq)
  .$.unstable.shape.fold('westcoast', env.range(-2, 4))
  .amp(env)
  .out()
